    StringEntity(key = "lumea_delete_confirmation_alert_message", value = "Please note that your MyPhilips Account is also used for any other Philips services (such as subscriptions and/or other Philips mobile apps) you may have created with the same email address. This means that if you delete your MyPhilips Account you will not be able to access any other Philips services you may have created with the same email address. \\n\\nIt will take 15 working days to delete your account inclusive all your data. After your account is deleted, you cannot recover your data anymore.", isAndroid = true, isIos = true, rowNumber = 539),
