    StringEntity(key = "lumea_skin_analysis_introduction_description", value = "The Skin-Selfie Analyzer technology analyzes your skin over time. It shows you the shine, smoothness, radiance, and more.", isAndroid = true, isIos = true, rowNumber = 559),
    StringEntity(key = "lumea_skin_analysis_intro_take_selfie_every_week", value = "Take a selfie every week", isAndroid = true, isIos = true, rowNumber = 560),
    StringEntity(key = "lumea_skin_analysis_intro_follow_care_tips", value = "Follow our care tips", isAndroid = true, isIos = true, rowNumber = 561),
    StringEntity(key = "lumea_skin_analysis_intro_discover_improvement", value = "Discover improvements", isAndroid = true, isIos = true, rowNumber = 562),
    StringEntity(key = "lumea_skin_analysis_info_text", value = "<b>What is Skin-Selfie Analyzer?</b>\\nLearn about your skin and track changes in your skin condition over time, to take the best possible care of your skin. It is as easy as taking a photo.\\n\\n<b>How it works</b>\\nOur Skin-Selfie Analyzer uses machine learning to analyze your skin based on the photo you provide.\\nYou can look at your skin\\'s shine, smoothness, radiance, and more.\\nThere are many factors that have an impact on the skin: weather, time of the month, treatments, age, and more. With Skin-Selfie Analyzer, you can track such changes in your skin condition over time.\\nTake a photo every week to closely monitor the changes.\\nPlease note that Skin-Selfie Analyzer is only intended to be used to provide skin care tips. It does not constitute a diagnosis or medical advice, and it should not be used to determine whether Lumea is suitable for your skin. Check the user manual to assess whether Lumea is right for you.", isAndroid = true, isIos = true, rowNumber = 563),
