    StringEntity(key = "lumea_skin_analysis_summary_overview", value = "Summary", isAndroid = true, isIos = true, rowNumber = 569),
    StringEntity(key = "lumea_skin_analysis_empty_screen_overview_desc", value = "Get to know your skin. Take a selfie every week and see how your skin changes over time.\\nIt is an easy way to understand how your skin reacts to different conditions like: weather, treatments, products, sleep and more.", isAndroid = true, isIos = true, rowNumber = 570),
