    StringEntity(key = "lumea_hair_counter_intro_title", value = "Track your hair reduction in 3 simple steps", isAndroid = true, isIos = true, rowNumber = 580),
    StringEntity(key = "lumea_hair_counter_intro_tip_take_a_photo", value = "Take a photo", isAndroid = true, isIos = true, rowNumber = 581),
