    StringEntity(key = "lumea_hair_counter_intro_tip_get_tips", value = "Get tips", isAndroid = true, isIos = true, rowNumber = 583),
    StringEntity(key = "lumea_hair_counter_info_content", value = "<b>What is Body Hair Analyzer?</b>\\nBody Hair Analyzer helps you to analyze the results of your hair reduction. It provides a simple and easy way to track your progress over time.\\n\\n<b>How it works</b>\\nIt\\\u2019s as easy as taking a photo. The Body Hair Analyzer technology shows you hair reduction over time. The photo will be saved, and you can compare the reduction with every treatment. Repeat the analysis during every treatment to compare and track the changes over time.\\nThe effect of IPL technology is very personal and many different factors impact the amount of hair reduction, for example, the thickness of the hairs, the tone of your skin and how you follow the treatment schedule.\\n\\n<b>Note</b>\\nPlease note that hair analysis is only intended to be used as a personal indication of your hair reduction. It cannot indicate the number of treatments you should do. We urge you to follow the treatment schedule. The Body Hair Analyzer should not be used to determine whether Lumea is suitable for your skin. Check the user manual to assess whether Lumea is right for you.", isAndroid = true, isIos = true, rowNumber = 584),
    StringEntity(key = "lumea_hair_counter_choose_body_area", value = "Which area would you like to analyze?", isAndroid = true, isIos = true, rowNumber = 585),
