    StringEntity(key = "lumea_hair_counter_tip_clear_photo", value = "Make sure you can see your hairs clearly. Photo should not be blurry.", isAndroid = true, isIos = true, rowNumber = 587),
    StringEntity(key = "lumea_hair_counter_tip_camera_straight", value = "Keep your camera straight and parallel to your skin.", isAndroid = true, isIos = true, rowNumber = 588),
    StringEntity(key = "lumea_hair_counter_tip_good_lighting", value = "Use good lighting, avoid shadows or glares on your skin. Make sure your body has a contrast with the background.", isAndroid = true, isIos = true, rowNumber = 589),
    StringEntity(key = "lumea_hair_counter_tip_no_tattoos", value = "Take a picture of an area where you have no tattoos.", isAndroid = true, isIos = true, rowNumber = 590),
    StringEntity(key = "lumea_hair_counter_result_what_does_it_mean_desc", value = "In your hair analysis results, the areas with hair growth are highlighted, allowing you to treat these areas if you would like to do so. If your hair analysis results do not appear to be accurate, please upload another photo and try again. For best results, ensure the area you wish to analyze is uncovered and evenly illuminated, without shadows on the surface of the skin. Please note that the thickness, length, and color of your hair may impact the accuracy of your hair analysis results.", isAndroid = true, isIos = true, rowNumber = 591),
    StringEntity(key = "lumea_hair_counter_bottomsheet_error", value = "Something went wrong", isAndroid = true, isIos = true, rowNumber = 592),
    StringEntity(key = "lumea_hair_counter_bottomsheet_error_desc", value = "Body Hair Analyzer wasn\u2019t able to assess your photo. Please try again, making sure the area you would like to analyze is visible and evenly illuminated.", isAndroid = true, isIos = true, rowNumber = 593),
    StringEntity(key = "lumea_tips_to_improve_section_title", value = "Tips to improve", isAndroid = true, isIos = true, rowNumber = 594),
    StringEntity(key = "lumea_hair_analysis_report_tip_release_flash_close_to_each_other", value = "Release the flashes close to each other to treat every part of your skin. If you miss spots, hairs might grow back here. However, make sure you flash the area only once.", isAndroid = true, isIos = true, rowNumber = 595),
    StringEntity(key = "lumea_hair_analysis_report_tip_stick_to_schedule", value = "Make sure to stick to the schedule!", isAndroid = true, isIos = true, rowNumber = 596),
    StringEntity(key = "lumea_hair_analysis_report_tip_schedule_treatment", value = "The treatment schedule is optimized for natural hair growth cycle. Follow the schedule in the app to ensure maximum impact of your treatment. Treating more often will not improve results. Also, make sure to do every treatment on time. Mark your treatment as done in the app so we can remind you of your next treatment.", isAndroid = true, isIos = true, rowNumber = 597),
    StringEntity(key = "lumea_hair_analysis_report_tip_right_intensity", value = "Use the right intensity setting", isAndroid = true, isIos = true, rowNumber = 598),
    StringEntity(key = "lumea_hair_analysis_report_tip_highest_comfortable_intensity", value = "Use the highest light intensity setting that is suitable for your skin tone and feels comfortable for the best possible results with Lumea IPL. You can find the light intensity setting suitable for you in the treatment tips in the app and in the device manual. Use the SmartSkin sensor to get an indication about what light intensity setting is suitable for you.", isAndroid = true, isIos = true, rowNumber = 599),
