    StringEntity(key = "lumea_calendar_legend_touchup_phase_desc", value = "After the [INITIAL PHASE], use your Lumea once every [X/7] weeks to maintain results. <br>Perform a treatment within [Y] days before or after the planned treatment date during the [TOUCH-UP]. <br><br> If you deviate from the treatment schedule, you may not achieve the intended results. You can continue with the original planned schedule or you may choose to restart the [INITIAL PHASE], but claimed results are based on the indicated treatment schedule and individual results vary.<br><br><b>Missed treatment</b><br>A treatment is missed if you don\\\u2019t complete it within [N] days before or after the planned treatment date. Try to stay closer to your planned treatment date. You can continue with the original planned schedule. You may add one additional bi-weekly treatment to your [INITIAL PHASE]. If you deviate from the treatment schedule, you may not achieve the intended results.", isAndroid = true, isIos = true, rowNumber = 800),
