    StringEntity(key = "lumea_moment_consent_title", value = "Securely store your data with us", isAndroid = true, isIos = true, rowNumber = 1222),
    StringEntity(key = "lumea_moment_consent_user_benefit_subtitle", value = "I want to back up and securely store my data, including sensitive data with Philips, so that I can easily access and restore this data (including my IPL treatment, skin and hair removal history) anytime and on any device.", isAndroid = true, isIos = true, rowNumber = 1223),
    StringEntity(key = "lumea_personalized_consent_nav_title", value = "To use SkinAI features, we need your consent", isAndroid = true, isIos = true, rowNumber = 1224),
    StringEntity(key = "lumea_marketing_opt_in_default_title", value = "Subscribe to our newsletter and be the first to know about exclusive deals", isAndroid = true, isIos = true, rowNumber = 1225),
    StringEntity(key = "lumea_analytics_consent_what_does_this_mean_title", value = "What does this mean?", isAndroid = true, isIos = true, rowNumber = 1226),
    StringEntity(key = "lumea_consent_cookies_help_text_description", value = "<b>Why do we ask for your consent?</b>\\nWe gather information on how you use the App and connected devices through cookies, similar technologies, and data you provide via in-app surveys or feedback forms. This helps us identify, analyze, and quickly fix issues like crashes, draw key insights to improve our current products and services, and develop new solutions that better suit your needs. Your data is {pseudonymized} and securely stored to protect your privacy.\\n\\nAdditionally, if you provide your explicit consent, Philips will collect your sensitive data. Sensitive data is information considered highly personal and requires the highest privacy protections. This includes but not limited to your skin or picture data.\\n\\nFor statistical and analytical purposes, we may also combine, aggregate, and anonymize this data.", isAndroid = true, isIos = true, rowNumber = 1227),
    StringEntity(key = "lumea_analytics_consent_what_does_this_mean_detail_title", value = "<b>What data are you providing to Philips?</b>", isAndroid = true, isIos = true, rowNumber = 1228),
    StringEntity(key = "lumea_privacy_pseudonymization", value = "Pseudonymization is a method where we replace your personal information, like your name, with a code or placeholder. This way, even if someone sees the data, they can't tell it's yours. It helps keep your identity safe and your information private.", isAndroid = true, isIos = true, rowNumber = 1229),
    StringEntity(key = "lumea_info_about_mobile_device_title", value = "Information about your mobile device", isAndroid = true, isIos = true, rowNumber = 1230),
    StringEntity(key = "lumea_info_about_mobile_device_description", value = "Such as anonymized visitor IDs, mobile device data including operating systems, orientation, device model and/or version, mobile dimension and screen size, resolution, timestamps, IP address, instance IDs, app version, device identifier, iOS hardware, iOS Identifier for Advertising, iOS Identifier for Vendors, Android Advertiser ID, device manufacturer, Android Hardware ID, Developer ID, application version, amount of RAM and disk space, CPU architecture, language, country, radio/network information, carrier, signal strength, jailbroken/rooted status of device, battery level and charging state, background state, app package name, pseudonymous app-instance identifier, associated RSID, installation UUID, property.", isAndroid = true, isIos = true, rowNumber = 1231),
    StringEntity(key = "lumea_info_about_lumea_device_description", value = "Such as your IPL model category, model number and where applicable, sensor data about the device's movement and orientation.", isAndroid = true, isIos = true, rowNumber = 1232),
    StringEntity(key = "lumea_info_about_app_usage_title", value = "Information about your app usage", isAndroid = true, isIos = true, rowNumber = 1233),
    StringEntity(key = "lumea_info_about_app_usage_description", value = "Such as information about your treatment program (treatment phase, interval, completion, number of treatments, intensity and comfort level, number of flashes and missed spots, body area length, missed or late treatment), app settings and usage (including your consents and Philips unique identifier)", isAndroid = true, isIos = true, rowNumber = 1234),
    StringEntity(key = "lumea_your_feedback_title", value = "Your feedback", isAndroid = true, isIos = true, rowNumber = 1235),
    StringEntity(key = "lumea_your_feedback_description", value = "Such as comments and feedback responses, and associated information such as mobile device ID, customer ID, OS name, version, build, hardware, carrier, Language, country, local device model, answers and comments, manufacturer, anonymized IP address, operating system.", isAndroid = true, isIos = true, rowNumber = 1236),
    StringEntity(key = "lumea_read_more_information_title", value = "For more information, please read our {Privacy notice}", isAndroid = true, isIos = true, rowNumber = 1237),
    StringEntity(key = "lumea_moment_consent_help_text_description", value = "Backing up your data is a service we provide at your request. This allows us to store your data on our servers, linked with your Philips account, so it can be safely restored if you delete the app or reinstall it on a new device. Since this involves storing {sensitive data},  we need your explicit consent. If you do not agree, you won't be able to restore your data or access your IPL treatment, hair removal and skin history. You can always change your mind and adjust your privacy settings within the app.", isAndroid = true, isIos = true, rowNumber = 1238),
    StringEntity(key = "lumea_moment_consent_sensitive_data", value = "Sensitive data is information considered highly personal and requires the highest privacy protections. This includes but not limited to your skin or picture data.", isAndroid = true, isIos = true, rowNumber = 1239),
    StringEntity(key = "lumea_moment_ipl_device_description", value = "Such as your IPL model category, model number.", isAndroid = true, isIos = true, rowNumber = 1240),
