    StringEntity(key = "lumea_info_about_your_audio_recording_title", value = "Information about your audio recording", isAndroid = true, isIos = true, rowNumber = 1249),
    StringEntity(key = "lumea_info_about_your_audio_recording_description", value = "Such as audio samples (less than 1 second).", isAndroid = true, isIos = true, rowNumber = 1250),
    StringEntity(key = "lumea_skin_consent_help_text_description", value = "<b>Why do we ask for your consent?</b>\\nWe process personal data, including sensitive data, to provide personalized outcomes such as tailored skin routines and hair removal tracing, experiences, and recommendations. By consenting, you agree to Philips processing your {sensitive data}, to offer these services. Without your consent, these features will not be available to you.", isAndroid = true, isIos = true, rowNumber = 1251),
    StringEntity(key = "lumea_skin_ai_consent_sensitive_data", value = "Sensitive data is information considered highly personal and requires the highest privacy protections. This includes for example your skin or picture data if you are using our Skin Analyzer feature.", isAndroid = true, isIos = true, rowNumber = 1252),
    StringEntity(key = "lumea_analaytics_consent_subtitle_text", value = "I consent to Philips collecting and analyzing my App and device data to improve its products and services (and develop new Lumea solutions).\\n\\nBy consenting, you'll be helping us make your experience even better.", isAndroid = true, isIos = true, rowNumber = 1253),
