    StringEntity(key = "lumea_moment_consent_what_does_this_mean_description_text", value = "Backing up your data is a service we provide at your request. This allows us to store your data on our servers, linked with your Philips account, so it can be safely restored if you delete the app or reinstall it on a new device. Since this involves storing <a href=\"iDForSensitiveData\">sensitive data</a>,\u00a0 we need your explicit consent. If you do not agree, you won\u2019t be able to restore your data or access your IPL treatment, hair removal and skin history. You can always change your mind and adjust your privacy settings within the app.", isAndroid = false, isIos = true, rowNumber = 1272),
    StringEntity(key = "lumea_sensitive_data_link", value = "sensitive data", isAndroid = true, isIos = true, rowNumber = 1273),
    StringEntity(key = "lumea_personalized_consent_what_does_this_mean_description", value = "<b>Why do we ask for your consent?</b>\\nWe process personal data, including sensitive data, to provide personalized outcomes such as tailored skin routines and hair removal tracing, experiences, and recommendations. By consenting, you agree to Philips processing your <a href=iDForSensitiveDataSkinAI>sensitive data</a>, to offer these services. Without your consent, these features will not be available to you.", isAndroid = false, isIos = true, rowNumber = 1274),
    StringEntity(key = "lumea_analytics_consent_what_does_this_mean_description_text", value = "<b>Why do we ask for your consent?</b>\\nWe gather information on how you use the App and connected devices through cookies, similar technologies, and data you provide via in-app surveys or feedback forms. This helps us identify, analyze, and quickly fix issues like crashes, draw key insights to improve our current products and services, and develop new solutions that better suit your needs. Your data is  <a href=\"iDForPseudonymized\">pseudonymized</a>\u00a0and securely stored to protect your privacy.\\n\\nAdditionally, if you provide your explicit consent, Philips will collect your sensitive data. Sensitive data is information considered highly personal and requires the highest privacy protections. This includes but not limited to your skin or picture data.\n\\nFor statistical and analytical purposes, we may also combine, aggregate, and anonymize this data", isAndroid = false, isIos = true, rowNumber = 1275),
