    StringEntity(key = "lumea_skin_consent_warning_profile_dialog_desc", value = "You understand and accept that if you revoke this consent, we will no longer be able to provide you certain services which use sensitive data.", isAndroid = true, isIos = true, rowNumber = 1281),
